// Generated from content\spelling.seed.json via scripts/generate-spelling-content.mjs
// Keep the Worker seed compressed so the deployed script stays under Cloudflare's Free plan size limit.
// The compressed payload keeps the editable bundle; duplicate wordBySlug indexes are rebuilt at runtime.

const SEEDED_SPELLING_CONTENT_BUNDLE_GZIP_BASE64 = "";

export const SEEDED_SPELLING_CONTENT_SUMMARY = {
  "wordListCount": 19,
  "wordCount": 1480,
  "sentenceCount": 3447,
  "releaseCount": 10,
  "errorCount": 0,
  "warningCount": 6,
  "publishedReleaseId": "spelling-r10",
  "publishedVersion": 10,
  "publishedAt": 1780695300000,
  "runtimeWordCount": 1480,
  "runtimeSentenceCount": 3447,
  "coverageTierCounts": {
    "statutoryCore": 213,
    "secureExtension": 1215,
    "enrichmentExtra": 52,
    "total": 1480
  },
  "statutoryCoreCount": 213,
  "secureExtensionCount": 1215,
  "enrichmentExtraCount": 52,
  "ok": true
};

let contentBundlePromise = null;
let publishedSnapshotPromise = null;

function decodeBase64(value) {
  const binary = atob(value);
  const bytes = new Uint8Array(binary.length);
  for (let index = 0; index < binary.length; index += 1) {
    bytes[index] = binary.charCodeAt(index);
  }
  return bytes;
}

function rebuildSnapshotIndexes(snapshot) {
  const words = Array.isArray(snapshot?.words) ? snapshot.words : [];
  return {
    ...(snapshot || {}),
    words,
    wordBySlug: Object.fromEntries(words.map((word) => [word.slug, word])),
  };
}

function rebuildBundleIndexes(bundle) {
  return {
    ...bundle,
    releases: (Array.isArray(bundle?.releases) ? bundle.releases : []).map((release) => ({
      ...release,
      snapshot: rebuildSnapshotIndexes(release?.snapshot),
    })),
  };
}

function resolvePublishedRelease(bundle) {
  const releases = Array.isArray(bundle?.releases) ? bundle.releases : [];
  const currentReleaseId = bundle?.publication?.currentReleaseId || '';
  const selected = currentReleaseId ? releases.find((release) => release.id === currentReleaseId) : null;
  if (selected) return selected;
  return [...releases]
    .filter((release) => release?.state === 'published' || release?.state === 'archived')
    .sort((a, b) => (Number(b?.version) || 0) - (Number(a?.version) || 0) || (Number(b?.publishedAt) || 0) - (Number(a?.publishedAt) || 0))[0] || null;
}

async function inflateJsonFromBase64(value) {
  if (typeof DecompressionStream !== 'function') {
    throw new Error('DecompressionStream is required to read the compressed spelling seed.');
  }
  const stream = new Blob([decodeBase64(value)]).stream().pipeThrough(new DecompressionStream('gzip'));
  return JSON.parse(await new Response(stream).text());
}

export function readSeededSpellingContentBundle() {
  if (!contentBundlePromise) {
    contentBundlePromise = inflateJsonFromBase64(SEEDED_SPELLING_CONTENT_BUNDLE_GZIP_BASE64)
      .then(rebuildBundleIndexes);
  }
  return contentBundlePromise;
}

export function readSeededSpellingPublishedSnapshot() {
  if (!publishedSnapshotPromise) {
    publishedSnapshotPromise = readSeededSpellingContentBundle()
      .then((bundle) => resolvePublishedRelease(bundle)?.snapshot || rebuildSnapshotIndexes(null));
  }
  return publishedSnapshotPromise;
}
